<?php
declare(strict_types=1);
$root=realpath(__DIR__.'/../marketplace');$repoRoot=realpath(__DIR__.'/..');if($root===false||$repoRoot===false)throw new RuntimeException('Marketplace application directory is missing.');
$required=['index.php'=>['Advertise','opportunities.php','pf_render_site_ad'],'dashboard.php'=>['ADVERTISER','campaigns.php','blog-campaigns.php','profile.php'],'profile.php'=>['pf_advertiser_profiles','contact_email','pf_legacy_advertiser_access_allowed'],'register.php'=>["'ADVERTISER'",'can_work','can_advertise','pf_advertiser_profiles'],'create-payment.php'=>['pf_payment_provider_ready','pf_payment_http'],'payment-return.php'=>['pf_verify_paystack_order','pf_capture_paypal_order'],'api/paystack-webhook.php'=>['HTTP_X_PAYSTACK_SIGNATURE','hash_hmac'],'api/paypal-webhook.php'=>['verify-webhook-signature','verification_status'],'bootstrap/payments.php'=>['pf_credit_payment_order','FOR UPDATE','PAYMENT_VERIFIED','DEPOSIT'],'admin/campaigns.php'=>['ADMIN_CAMPAIGN_','pf_sync_blog_campaign'],'bootstrap/app.php'=>['pf_require_advertiser','410'],'admin/index.php'=>['ACTIVE ADVERTISERS','placements.php','finance.php']];
$errors=[];foreach($required as $path=>$needles){$content=@file_get_contents($root.'/'.$path);if($content===false){$errors[]=$path.' is missing';continue;}foreach($needles as $needle)if(!str_contains($content,$needle))$errors[]=$path.' missing marker '.$needle;}
foreach(['tasks.php','my-submissions.php','withdraw.php','dispute.php','fund-campaign.php','admin/disputes.php'] as $path){$content=@file_get_contents(str_starts_with($path,'tools/')?$repoRoot.'/'.$path:$root.'/'.$path);if($content===false||!str_contains($content,str_starts_with($path,'tools/')?'SYSTEM_AD_CAMPAIGN_EXPIRED':'http_response_code(410)'))$errors[]=$path.' must return HTTP 410';}
$expiry=@file_get_contents($repoRoot.'/tools/expire-ad-campaigns.php');if($expiry===false||!str_contains($expiry,'SYSTEM_AD_CAMPAIGN_EXPIRED')||!str_contains($expiry,'SITE_DISPLAY')||!str_contains($expiry,'BLOG_SPONSORED'))$errors[]='tools/expire-ad-campaigns.php is missing required expiry behavior';
if($errors){fwrite(STDERR,implode(PHP_EOL,$errors).PHP_EOL);exit(1);}echo "Advertiser-only product contract checks passed.\n";
